const TABLES: Readonly<Record<NextMuxDesktopLocale, Table>> = { 'zh-CN': zhCN, 'zh-TW': zhTW, en, ja, ko, es, fr, de, 'pt-BR': ptBR, ru, ar, hi };

export type ComicChatTextKey = Key;

function uncheckedComicChatText(locale: NextMuxDesktopLocale, key: ComicChatTextKey, values: Readonly<Record<string, string | number>> = {}): string {
    const table = TABLES[locale] || en;
    return (table[key] ?? en[key]).replace(/\{(\w+)\}/g, (_match, name: string) => String(values[name] ?? ''));
}

export const COMIC_CHAT_TEXT_LOCALES = Object.keys(TABLES);

/** Text lookups that never throw: an unknown key or language falls back (see nextmux-copy-fallback.ts). */
export function comicChatText(locale: Parameters<typeof uncheckedComicChatText>[0], key: Parameters<typeof uncheckedComicChatText>[1], ...rest: AfterLocaleAndKey<Parameters<typeof uncheckedComicChatText>>): string {
    return totalCopy(locale, key, language => uncheckedComicChatText(language, key, ...rest));
}
